def substitution_loss(typ: str) -> Optional[str]:
    """``"element <Abaqus type> -> <ccx type>"`` when ccx_element_type replaces the element's
    formulation (reduced physics), or None when ccx runs that element: natively, under its
    coupled temperature-displacement base name (a T suffix), unchanged (types ccx stops on), or
    through an exact substitution (EXACT_SUBSTITUTIONS)."""
    t = typ.upper()
    if t in CCX_ELEMENTS or t in EXACT_SUBSTITUTIONS:
        return None
    sub = ccx_type(t)
    if sub == t:
        return None
    base, dropped = t, ""
    while len(base) > 1 and base[-1] in "THP" and base not in CCX_ELEMENTS and \
            base not in ELEMENT_TYPE_MAP:
        dropped += base[-1]
        base = base[:-1]
    if dropped and set(dropped) == {"T"} and (base in CCX_ELEMENTS or base in EXACT_SUBSTITUTIONS):
        return None
    return f"element {t} -> {sub}"

# Element types CalculiX supports directly (verified, ccx 2.22).  Used to tell a
# direct passthrough from one needing substitution / a warning.
CCX_ELEMENTS = {
    "C3D4", "C3D6", "C3D8", "C3D8R", "C3D8I", "C3D10", "C3D10T", "C3D15", "C3D20",
    "C3D20R", "C3D20RI", "F3D4", "F3D6", "F3D8", "D",
    "S3", "S4", "S4R", "S6", "S8", "S8R", "US3",
    "M3D3", "M3D4", "M3D4R", "M3D6", "M3D8", "M3D8R",
    "CPS3", "CPS4", "CPS4R", "CPS6", "CPS8", "CPS8R",
    "CPE3", "CPE4", "CPE4R", "CPE6", "CPE8", "CPE8R",
    "CAX3", "CAX4", "CAX4R", "CAX6", "CAX8", "CAX8R",
    "B21", "B31", "B31R", "B32", "B32R", "T2D2", "T3D2", "T3D3",
    "SPRING1", "SPRING2", "SPRINGA", "DASHPOTA", "GAPUNI", "MASS", "DCOUP3D",
    "DC3D4", "DC3D6", "DC3D8", "DC3D10", "DC3D15", "DC3D20", "U1",
}
# Element families with no geometric CalculiX equivalent at all.
UNSUPPORTED_ELEM_PREFIXES = ("COH", "GK", "GKPS", "GKAX", "CONN", "ROTARYI")

# Abaqus element families ccx 2.23 has no element for, nor the converter a stand-in: written
# as they are, so ccx stops ("... is an unknown element type"), and named in the report.
# (pattern, family, examples); the group is the node count (JOINTC: 2).
LACKING_ELEMENTS = (
    (r"C(?:PS|PE|AX|3D)(\d+)R?E", "piezoelectric", "CPS4E, CAX8RE, C3D8E, C3D20RE"),
    (r"DC(?:1D|2D|3D|AX)(\d+)E", "coupled thermal-electrical", "DC2D4E, DC3D8E"),
    (r"Q3D(\d+)R?H?", "coupled thermal-electrical-structural", "Q3D8, Q3D8R, Q3D20"),
    (r"CIN(?:PS|PE|AX|3D)(\d+)R?", "infinite", "CINPS4, CINAX4, CIN3D8, CIN3D12R"),
    (r"ACIN(?:2D|3D|AX)(\d+)", "acoustic infinite", "ACIN2D2, ACIN3D3, ACIN3D4"),
    (r"AC(?:1D|2D|3D|AX)(\d+)", "acoustic", "AC2D4, AC3D4, AC3D8, AC3D20"),
    (r"JOINTC()", "joint", "JOINTC"),
)


def lacking_element(typ: str) -> Optional[Tuple[str, int]]:
    """(family, node count) of an Abaqus element type in LACKING_ELEMENTS, else None."""
    for pat, what, _ in LACKING_ELEMENTS:
        m = re.fullmatch(pat, typ.upper())
        if m:
            return what, int(m.group(1) or 2)
    return None

# Integration points per (emitted ccx) element type — empirically probed against ccx 2.22
# by counting *EL PRINT stress rows on single-element decks.  NOTE the 2D counts are the
# counts of the internally EXPANDED 3D elements (ccx expands plane/axisym to bricks and
# wedges: CPS4 -> 8 like C3D8, CPS8 -> 27 like C3D20, CPS3 -> 2 like C3D6), which is what
# *INITIAL CONDITIONS, TYPE=STRESS/... addresses.
ELEMENT_IP_COUNT = {
    "C3D4": 1, "C3D6": 2, "C3D8": 8, "C3D8R": 1, "C3D8I": 8, "C3D10": 4, "C3D10T": 4,
    "C3D15": 9, "C3D20": 27, "C3D20R": 8, "C3D20RI": 8,
    "CPS3": 2, "CPS4": 8, "CPS4R": 1, "CPS6": 9, "CPS8": 27, "CPS8R": 8,
    "CPE3": 2, "CPE4": 8, "CPE4R": 1, "CPE6": 9, "CPE8": 27, "CPE8R": 8,
    "CAX3": 2, "CAX4": 8, "CAX4R": 1, "CAX6": 9, "CAX8": 27, "CAX8R": 8,
}


def element_node_count(typ: str) -> Optional[int]:
    """Node count used to parse connectivity, tolerant of the coupled-temperature ``T``,
    hybrid ``H`` and pore-pressure ``P`` suffixes (none changes the node count, e.g.
    ``C3D8T``, ``CAX4RT``, ``C3D20HT``, ``CAX4P`` all match their base's count)."""
    typ = typ.upper()
    if typ in ELEMENT_NNODES:
        return ELEMENT_NNODES[typ]
    if typ in ELEMENT_TYPE_MAP:                 # mapped types keep their node count
        return ELEMENT_NNODES.get(ELEMENT_TYPE_MAP[typ])
    base = typ
    while base and base[-1] in ("T", "H", "P"):
        base = base[:-1]
        if base in ELEMENT_NNODES:
            return ELEMENT_NNODES[base]
        if base in ELEMENT_TYPE_MAP:
            return ELEMENT_NNODES.get(ELEMENT_TYPE_MAP[base])
    lacking = lacking_element(typ)
    return lacking[1] if lacking else None


def split_suffixes(typ: str) -> Tuple[str, str]:
    """(base, dropped letters) of a suffix element — coupled-temperature ``T``, hybrid ``H``,
    pore-pressure ``P`` in any combination (C3D8T, CAX4RP, C3D8PT, C3D20RHT): trailing
    suffix letters stripped until a known base is reached.  ``(typ, "")`` for any other
    type, a known one included."""
    typ = typ.upper()
    base, dropped = typ, ""
    while len(base) > 1 and base[-1] in "THP" and \
            base not in CCX_ELEMENTS and base not in ELEMENT_TYPE_MAP:
        dropped += base[-1]
        base = base[:-1]
    if dropped and (base in CCX_ELEMENTS or base in ELEMENT_TYPE_MAP):
        return base, dropped
    return typ, ""


def keeps_dof8(typ: str) -> bool:
    """Whether elements of Abaqus type ``typ`` carry DOF 8 (pore, fluid or acoustic
    pressure) in the converted deck: acoustic and acoustic-structural interface elements,
    hydrostatic fluid, fluid link and fluid pipe elements, ccx's CFD elements and user
    elements, all emitted as they are.  Pore-pressure elements lose it with their ``P``
    suffix (ccx_element_type)."""
    return re.match(r"AC|ASI|F(2D2|AX2|3D\d+|LINK|PC?[23]D2)$|V?U\d+$", typ.upper()) is not None


def ccx_element_type(typ: str, report: "Report") -> str:
    """Return the CalculiX element name for an Abaqus type, substituting where
    needed (node-count preserving) and warning on anything not directly supported."""
    typ = typ.upper()
    if typ in ELEMENT_TYPE_MAP:
        sub = ELEMENT_TYPE_MAP[typ]
        seen = {typ}
        while sub not in CCX_ELEMENTS and sub in ELEMENT_TYPE_MAP and sub not in seen:
            seen.add(sub)                       # e.g. B23 -> B33 -> B31
            sub = ELEMENT_TYPE_MAP[sub]
        if typ.startswith(("COH", "GK")):
            report.warn(f"Element {typ} has no ccx formulation; approximated by the continuum "
                        f"element {sub} (node-count-preserving, runs as a thin elastic layer). The "
                        f"cohesive/gasket behaviour (separation/closure) is LOST, and a ZERO-thickness "
                        f"layer fails with a nonpositive-jacobian error — give the layer a small finite "
                        f"thickness or remodel with contact/*SPRING. Verify the result.", once=True)
        elif typ in EXACT_SUBSTITUTIONS:
            report.note(f"Element {typ} -> {sub}: the same solution — {EXACT_SUBSTITUTIONS[typ]}.",
                        once=True)
        else:
            report.warn(f"Element {typ} -> {sub}: ccx has no {typ}, and {sub} is a different element "
                        f"formulation ({SUBSTITUTION_LOSS.get(typ, 'node-count-preserving stand-in')}), "
                        f"so the results differ from Abaqus'.", once=True)
        return sub
    if typ in CCX_ELEMENTS:
        return typ
    # Suffix elements: warn once per dropped capability, and resolve the base (which may
    # itself need mapping, e.g. C3D10MT -> C3D10M -> C3D10).
    base, dropped = split_suffixes(typ)
    if dropped:
        if "T" in dropped:
            report.warn(f"Element {typ} -> {base} (CalculiX uses the base element for coupled "
                        f"temperature-displacement; the temperature DOF comes from the step).", once=True)
        if "H" in dropped and typ in EXACT_SUBSTITUTIONS:
            report.note(f"Element {typ} -> {base}: the same solution — {EXACT_SUBSTITUTIONS[typ]}.",
                        once=True)
        elif "H" in dropped:
            report.warn(f"Element {typ} -> {base}: CalculiX has no hybrid (mixed displacement-"
                        f"pressure) formulation; the displacement element differs from Abaqus' "
                        f"hybrid one (its fully integrated linear elements also lack Abaqus' "
                        f"selectively reduced volume terms), most for nearly incompressible "
                        f"materials.", once=True)
        if "P" in dropped:
            report.warn(f"Element {typ} -> {base}: ccx has no pore-pressure (coupled u-p) element; "
                        f"the pore-pressure DOF is dropped and only the mechanical response is solved — "
                        f"consolidation/seepage is NOT modelled. Verify.", once=True)
        return ccx_element_type(base, report)
    if typ in SURFACE_ELEMENTS:                 # only when the conversion had to keep them
        report.warn(f"Element {typ} is an Abaqus surface element; ccx has none and stops with "
                    f"'*ERROR reading *ELEMENT' (see the warning on why the conversion kept it).",
                    once=True)
        return typ
    if typ.startswith(("R3D", "RB2", "RB3", "RAX", "R2D")):
        report.warn(f"Element {typ} is a rigid element that the conversion left as it is (see the "
                    f"warning on why); ccx has no rigid element and stops with '*ERROR reading "
                    f"*ELEMENT'.", once=True)
        return typ
    if typ.startswith(UNSUPPORTED_ELEM_PREFIXES):
        report.warn(f"Element {typ} (cohesive/gasket/connector/rotary-inertia) has NO CalculiX "
                    f"equivalent; emitted unchanged. Remodel with contact, *SPRING/*GAP, *MPC or "
                    f"*MASS — the deck will not run until this is addressed.", once=True)
        return typ
    lacking = lacking_element(typ)
    if lacking:
        report.warn(f"Element {typ} is an Abaqus {lacking[0]} element: ccx 2.23 has none, and the "
                    f"converter no stand-in, so it is emitted unchanged and ccx stops ('*ERROR "
                    f"reading *ELEMENT: {typ} is an unknown element type').", once=True)
        return typ
    report.warn(f"Element {typ} is unknown to this converter; emitted unchanged — confirm your "
                f"ccx version supports it.", once=True)
    return typ


@functools.lru_cache(maxsize=None)
def ccx_type(typ: str) -> str:
    """ccx_element_type without its notes and warnings (emit_geometry gives those)."""
    return ccx_element_type(typ, Report())


SHELL_TYPES = {t for t in ELEMENT_NNODES if (t[0] == "S" and not t.startswith("SPRING")) or t.startswith("DS")}
BEAM_TYPES = {t for t in ELEMENT_NNODES if t[0] == "B" or t.startswith(("T2D", "T3D", "PIPE"))}
COMPOSITE_SHELL_OK = {"S6", "S8R"}  # CalculiX restricts composite shells to these
SHEET_SHELLS = {"S3", "S4", "S4R", "S6", "S8", "S8R"}   # the shells ccx expands (not SC6R / SC8R)
# ccx 2.23 stops on *SHELL SECTION, COMPOSITE on any other shell ('*ERROR reading *SHELL
# SECTION', probed on S3, S4, S4R, S8): emitted linear shell -> the quadratic shell its
# composite section runs on, with a node at the middle of every edge (_plan_quadratic_shells)
COMPOSITE_SHELL_UPGRADE = {"S3": "S6", "S4": "S8R", "S4R": "S8R"}
# Continuum shells under a composite section: one ccx solid per ply (_plan_ply_split); the
# default limit on the solids that adds (--max-ply-elements)
PLY_SOLID = {"SC8R": "C3D8I", "SC6R": "C3D6"}
PLY_SPLIT_LIMIT = 1000000
# Quadratic membranes, which ccx 2.23 expands with a mid-thickness node free in each element
# (_plan_quadratic_membranes) -> the solid the converter writes each element as; M3D9 / M3D9R
# lose their centre node (the 8-node serendipity interpolation)
QUAD_MEMBRANE_SOLID = {"M3D6": "C3D15", "M3D8": "C3D20", "M3D8R": "C3D20R", "M3D9": "C3D20",
                       "M3D9R": "C3D20R"}
# ccx 2.23 expands a 3-node beam into a 20-node brick: B32 integrated at 3 x 3 x 3 points, B32R
# at 2 x 2 x 2 (*EL PRINT COORD).  Abaqus integrates its quadratic beams (B22, B32, PIPE22,
# PIPE32) at 2 points along the beam (Abaqus 2017 "Beam element library", numbering of
# integration points), and B32R gives their solution on the deck's mesh where B32 locks
# (probed on 2.23: a RECT cantilever's tip deflection under an end load is exact on 1 to 16
# B32R, 0.77 / 0.95 / 0.993 of it on 1 / 2 / 4 B32; frequencies, buckling loads and large
# deflections alike), so every 3-node beam is written as B32R.  Two limits of its reduced
# integration, not of the conversion: one B32R alone between two nodes that are no knots has
# zero-energy modes (*FREQUENCY stops in ARPACK, *BUCKLE finds spurious modes); and in a 3-D
# NLGEOM step members of 2-4 elements can stop converging under large rotations (an
# out-of-plane instability; holding DOF 3, as in a 2-D model, removes it).
QUADRATIC_BEAM = "B32R"
# *EL PRINT rows ccx 2.23 writes per B32R element under a RECT or CIRC section: 50, of which
# the first 8 are its integration points and the rest no results at any point (PIPE: 16, BOX:
# 32, all of them integration points)
B32R_PRINT_ROWS = {"RECT": 8, "CIRC": 8}
# ccx 2.23 stops on a 2-node beam with a circular section ("Please use quadratic elements
# for beams with circular cross section": it expands a linear beam into an 8-node brick,
# whose corner nodes cannot follow a circle) and accepts PIPE and BOX sections only on B32R
# ("*BEAM SECTION of type PIPE can only be used for B32R elements": their integration-point
# schemes are defined on the expanded C3D20R).  Emitted 2-node type -> the 3-node beam such
# elements become, with a midside node (ccx runs B21 as a B31).
QUADRATIC_UPGRADE = {"B21": QUADRATIC_BEAM, "B31": QUADRATIC_BEAM, "B31R": QUADRATIC_BEAM}
# the *BEAM SECTION, SECTION= values that need it (THICK PIPE is emitted as PIPE)
SECTION_BEAM_UPGRADE = ("CIRC", "PIPE", "THICK PIPE", "BOX")

# ccx 2.23's own 2-node beam, the user element U1, carries a section given by its properties
# (*BEAM SECTION, SECTION=GENERAL), which the expanded beams cannot.  Probed on 2.23
# (cantilevers of 1 to 100 elements, frames, against beam theory):
# * declared by U1_CARD, without a data line, before *ELEMENT, TYPE=U1;
# * section data: A, I1, I12, I2, k on the first line — I1 resists a displacement along n1
#   (Abaqus' I22, the integral of x1^2), I2 one along n2 = t x n1 (Abaqus' I11), I12 must be 0
#   ('no nonzero cross moment of inertia'), k A is the shear area; more values change
#   nothing — and n1 on the required second line, which U1 does not project: an n1 that is
#   not normal to the element bends it wrongly.  ELSET is read to 20 characters (a longer
#   name: 'element set ... has not yet been defined'), MATERIAL in full;
# * bending is exact Euler-Bernoulli (cubic) on any mesh when k A is large.  The shear term
#   is wrong: one element deflects like a Timoshenko beam with phi (phi - 3) / (1 + phi) for
#   phi = 12 E I / (k G A L^2), stiffer than Euler-Bernoulli, so U1_PHI keeps phi negligible
#   (an Euler-Bernoulli beam, also if a later ccx fixes the term);
# * torsion is G (I1 + I2), with no torsion constant of its own, and *ELASTIC stops on
#   nu >= 0.5: a copy of the material can set G to G J / (I1 + I2) only where
#   G J > E (I1 + I2) / 3;
# * the material must be linear elastic and isotropic: a plastic one stops ccx ('no
#   anisotropic material'), and so do ORIENTATION, OFFSET1 and OFFSET2; a thermal strain
#   comes out n times too large on n elements (no error);
# * linear *STATIC, *FREQUENCY, *MODAL DYNAMIC and *STEADY STATE DYNAMICS run; NLGEOM, *BUCKLE
#   and *DYNAMIC stop ('no second order', 'no buckling', 'no initial strains allowed').  Its
#   nodal forces are wrong (the axial force has the wrong sign at the first node, the shear
#   force at the second): RF at its nodes is wrong, and a step ccx iterates (a plastic or
#   contact part elsewhere) diverges;
# * GRAV and CENTRIF stop ccx ('no body forces'); *DLOAD P1 / P2 on it apply nothing;
# * S holds section forces (N, the moments about n2 and n1, the shear forces along n1 and
#   n2, and the torque times k), E the matching strains; the .frd holds its own nodes;
# * its mass matrix converges to the Euler-Bernoulli beam with rotary inertia, at O(h^2);
# * ccx stops ('gen3delem: first thickness ... is zero') when the deck has any element it
#   expands (beams, trusses, shells, membranes, plane elements) besides U1, even an
#   unconnected one; solids, springs, dashpots and point masses mix with it.
U1_CARD = "*USER ELEMENT, TYPE=U1, INTEGRATION POINTS=2, MAXDOF=6, NODES=2"
U1_PHI = 1e-10                    # 12 E I / (k G A L^2) on every U1 element (at most)
# Abaqus' 2-node beams, which U1 replaces (a 2-D one in a plane); the cubic B23 / B33 are
# Euler-Bernoulli beams like U1, the others shear-flexible
U1_TYPES = {"B21", "B21H", "B23", "B23H", "B31", "B31H", "B33", "B33H"}
U1_EULER_BERNOULLI = {"B23", "B33"}
# library profiles whose properties the converter computes from their dimensions
U1_PROFILES = {"I", "HEX", "TRAPEZOID", "ARBITRARY", "L"}
# *BEAM GENERAL SECTION profiles that ccx's expanded beams have (Converter._general_as_beam_section)
GENERAL_EXPANDED = {"RECT", "CIRC", "PIPE", "BOX"}
# ccx types that can share a deck with U1 (ccx expands none of them)
U1_COMPANIONS = ("C3D", "F3D", "SPRING", "DASHPOT", "MASS")
# material cards a U1 beam's material may have (ccx stops on, or iterates with, the others:
# MATERIAL_OPTION_CARDS, and these)
U1_MATERIAL_CARDS = {"MATERIAL", "ELASTIC", "DENSITY", "EXPANSION", "DAMPING", "CONDUCTIVITY",
                     "SPECIFIC HEAT"}
U1_NONLINEAR_CARDS = {"ANISOTROPIC HYPERELASTIC", "LOW DENSITY FOAM", "VISCOUS", "HYSTERESIS",
                      "EOS", "TENSILE FAILURE", "SHEAR FAILURE", "GASKET THICKNESS BEHAVIOR"}


@dataclass
class BeamSection:
    """A beam cross-section's properties in the axes of its profile (x1 along n1, x2 along
    n2): area, i11 = integral of x2^2, i12 = integral of x1 x2, i22 = integral of x1^2 (about
    the centroid), torsion constant j, and the centroid (c1, c2) and shear centre (s1, s2)
    relative to the beam node."""
    area: float
    i11: float
    i12: float
    i22: float
    j: float
    c1: float = 0.0
    c2: float = 0.0
    s1: float = 0.0
    s2: float = 0.0
    exact_j: bool = True                        # Abaqus' own value of j (not a numerical one)
    shear_known: bool = True                    # (s1, s2) known


def i_section(l: float, h: float, b1: float, b2: float, t1: float, t2: float,
              t3: float) -> Union[BeamSection, str]:
    """Abaqus' I profile (*BEAM SECTION, SECTION=I: l, h, b1, b2, t1, t2, t3): the bottom
    flange b1 x t1 and the top flange b2 x t2 centred on the web of thickness t3 between them,
    the beam node l above the bottom face; one flange zero is a T.  Abaqus' own general-section
    form of its verification I profile (Verification Guide, "Verification of beam elements and
    section types": eb32idsd, eb32gisd) has these values: three rectangles (A, I11, I22) and
    the open thin-walled torsion constant, sum of b t^3 / 3, with the web between the flanges;
    the shear centre is the thin-walled one, on the web at the flanges' I22-weighted midline
    position.  The reason when the dimensions make no I or T."""
    tee = (b1 == 0.0 and t1 == 0.0) or (b2 == 0.0 and t2 == 0.0)
    if min(h, t3) <= 0 or min(b1, b2, t1, t2) < 0 or h - t1 - t2 <= 0 or \
            (not tee and min(b1, b2, t1, t2) <= 0):
        return "the I profile's dimensions make no I or T (nonpositive, or the flanges overlap)"
    hw = h - t1 - t2
    rects = [(b1, t1, t1 / 2.0), (b2, t2, h - t2 / 2.0), (t3, hw, t1 + hw / 2.0)]  # w, d, y
    area = sum(w * d for w, d, _ in rects)
    ybar = sum(w * d * y for w, d, y in rects) / area
    i11 = sum(w * d ** 3 / 12.0 + w * d * (y - ybar) ** 2 for w, d, y in rects)
    i22 = sum(d * w ** 3 / 12.0 for w, d, _ in rects)
    j = (b1 * t1 ** 3 + b2 * t2 ** 3 + hw * t3 ** 3) / 3.0
    f1, f2 = t1 * b1 ** 3, t2 * b2 ** 3
    if f1 + f2 == 0.0:
        return "the I profile has no flange"
    ys = t1 / 2.0 + (h - t1 / 2.0 - t2 / 2.0) * f2 / (f1 + f2)
    return BeamSection(area, i11, 0.0, i22, j, 0.0, ybar - l, 0.0, ys - l)


def hex_section(d: float, t: float) -> Union[BeamSection, str]:
    """Abaqus' HEX profile (d, t): a regular hexagonal tube with its outer circumradius d (the
    vertices on the 1-axis) and wall thickness t, the node at its centre.  The exact annulus —
    Abaqus' verification hexagon (d 2, t .2) has the reference tip deflection .3489 = P L^3 /
    3 E I with it — and the closed thin-walled torsion constant 4 Ac^2 / (perimeter / t) on
    the wall's median line, Abaqus' formula for closed thin-walled sections."""
    ri = d - 2.0 * t / math.sqrt(3.0)
    if min(d, t) <= 0 or ri <= 0:
        return "the HEX profile's dimensions are not positive, or its wall fills it"
    i = 5.0 * math.sqrt(3.0) / 16.0 * (d ** 4 - ri ** 4)
    rm = (d + ri) / 2.0
    return BeamSection(1.5 * math.sqrt(3.0) * (d * d - ri * ri), i, 0.0, i, 4.5 * rm ** 3 * t)


def rect_torsion(a: float, b: float) -> float:
    """The St. Venant torsion constant of a solid a x b rectangle (series solution)."""
    w, h = min(a, b), max(a, b)
    s = sum(math.tanh(n * math.pi * h / (2.0 * w)) / n ** 5 for n in range(1, 40, 2))
    return h * w ** 3 / 3.0 * (1.0 - 192.0 / math.pi ** 5 * w / h * s)


def trapezoid_section(a: float, b: float, c: float, d: float) -> Union[BeamSection, str]:
    """Abaqus' TRAPEZOID profile (a, b, c, d): the bottom width a, the height b and the top
    width c, symmetric about the 2-axis, the node d above the bottom.  Exact area and second
    moments.  Abaqus computes its torsion constant numerically (a Prandtl stress-function model
    of the section), and its shear centre is off the centroid in general: here the rectangle
    of the mean width gives j, and the shear centre is not known."""
    if min(a, b, c) < 0 or b <= 0 or a + c <= 0:
        return "the TRAPEZOID profile's dimensions are not positive"
    area = b * (a + c) / 2.0
    ybar = b * (a + 2.0 * c) / (3.0 * (a + c))
    i11 = b ** 3 * (a * a + 4.0 * a * c + c * c) / (36.0 * (a + c))
    i22 = b * (a + c) * (a * a + c * c) / 48.0
    return BeamSection(area, i11, 0.0, i22, rect_torsion((a + c) / 2.0, b), 0.0, ybar - d,
                       exact_j=False, shear_known=False)


def arbitrary_section(recs: List[List[str]]) -> Union[BeamSection, str]:
    """Abaqus' ARBITRARY profile: n thin-walled straight segments between points in the section
    axes (line 1: n, the first two points and the first thickness; then one point and the
    thickness of the segment ending there per line).  Abaqus integrates each segment along its
    line ("no bending stiffness about the line joining the end points of the segment"), so
    the area and second moments are line integrals of the thickness; it computes the torsion
    constant numerically (a Prandtl model), here the open thin-walled sum of L t^3 / 3, or
    4 Ac^2 / sum of L / t for a single closed cell; the shear centre is not known."""
    try:
        n = int(float(recs[0][0]))
        first = [pf(x) if x else 0.0 for x in (recs[0][1:6] + [""] * 5)[:5]]
        pts = [(first[0], first[1]), (first[2], first[3])]
        ts = [first[4]]
        for r in recs[1:n]:
            v = [pf(x) if x else 0.0 for x in (r[:3] + [""] * 3)[:3]]
            pts.append((v[0], v[1]))
            ts.append(v[2])
    except (IndexError, ValueError):
        return "the ARBITRARY profile's data do not read as numbers"
    if n < 2 or len(ts) != n or min(ts) < 0:
        return "the ARBITRARY profile needs at least two segments, each with a thickness"
    segs = [(pts[k], pts[k + 1], ts[k], math.dist(pts[k], pts[k + 1])) for k in range(n)]
    area = sum(t * ln for _, _, t, ln in segs)
    if area <= 0:
        return "the ARBITRARY profile has no area"
    c1 = sum(t * ln * (p[0] + q[0]) / 2.0 for p, q, t, ln in segs) / area
    c2 = sum(t * ln * (p[1] + q[1]) / 2.0 for p, q, t, ln in segs) / area
    cc = (c1, c2)

    def moment(i: int, j: int) -> float:
        """The integral of t (x_i - c_i)(x_j - c_j) along the segments (exact on straight ones)."""
        return sum(t * ln * (2.0 * (p[i] - cc[i]) * (p[j] - cc[j]) + (p[i] - cc[i]) * (q[j] - cc[j]) +
                             (q[i] - cc[i]) * (p[j] - cc[j]) + 2.0 * (q[i] - cc[i]) * (q[j] - cc[j])) / 6.0
                   for p, q, t, ln in segs)
    size = max(ln for *_, ln in segs)
    if math.dist(pts[0], pts[-1]) <= 1e-9 * size and all(t > 0 for t in ts):
        enclosed = abs(sum(p[0] * q[1] - q[0] * p[1] for p, q, _, _ in segs)) / 2.0
        j = 4.0 * enclosed ** 2 / sum(ln / t for _, _, t, ln in segs)
    else:
        j = sum(ln * t ** 3 for _, _, t, ln in segs) / 3.0
    return BeamSection(area, moment(1, 1), moment(0, 1), moment(0, 0), j, c1, c2,
                       exact_j=False, shear_known=False)


def beam_n1_line(b: "Block") -> Optional[int]:
    """The index in ``b.data`` of the n1 line of a *BEAM SECTION / *BEAM GENERAL SECTION card,
    or None when it has none.  Blank data lines are not kept, so a blank (default) n1 line is
    not in ``b.data`` and the lines are counted: the geometry (an ARBITRARY profile's segment
    lines, a TAPER section's two lines; a MESHED section starts with n1), the n1 line, then a
    general section's line of E, G, ...  (A general section with temperature-dependent moduli
    has several such lines: it reads as having none.)"""
    sec = (b.param("SECTION") or ("GENERAL" if b.keyword == "BEAM GENERAL SECTION" else "")
           ).strip().upper()
    data = [ln for ln in b.data if ln.strip()]
    geo = 1
    if sec == "ARBITRARY":
        try:
            geo = int(float(data[0].split(",")[0]))
        except (IndexError, ValueError):
            return None
    elif b.keyword == "BEAM GENERAL SECTION" and sec == "MESHED":
        return 0 if len(data) == 3 else None
    elif b.keyword == "BEAM GENERAL SECTION" and b.has("TAPER"):
        geo = 2
    if b.keyword == "BEAM GENERAL SECTION" and sec != "NONLINEAR GENERAL":
        return geo if len(data) == geo + 2 else None
    return geo if len(data) > geo else None


def beam_section_properties(section: str, recs: List[List[str]]) -> Union[BeamSection, str]:
    """The properties of a beam section from its first data line(s): SECTION=GENERAL of
    *BEAM GENERAL SECTION (A, I11, I12, I22, J; the centroid at the node, blanks zero), or a
    profile of U1_PROFILES; the reason when they cannot be had."""
    if section == "ARBITRARY":
        return arbitrary_section(recs)
    first = list(recs[0]) if recs else []
    while first and first[-1] == "":
        first.pop()
    try:
        v = [pf(x) if x else 0.0 for x in first]
    except ValueError:
        return "a section value is not a number (a *PARAMETER?)"
    if section == "GENERAL":
        if len(v) < 2:
            return "SECTION=GENERAL needs A, I11, I12, I22 and J on its first line"
        area, i11, i12, i22, j = (v + [0.0] * 5)[:5]
        return BeamSection(area, i11, i12, i22, j)
    need = {"I": 7, "HEX": 2, "TRAPEZOID": 4}.get(section)
    if need and len(v) < need:
        return f"SECTION={section} needs {need} dimensions"
    if section == "I":
        return i_section(*v[:7])
    if section == "HEX":
        return hex_section(*v[:2])
    if section == "TRAPEZOID":
        return trapezoid_section(*v[:4])
    if section == "L":
        return ("Abaqus puts the L profile's beam node where its legs' median lines meet, never at "
                "its centroid, and U1 has no offset")
    return f"SECTION={section} has no U1 conversion"


def principal_section(p: BeamSection) -> Tuple[float, float, float]:
    """(alpha, ia, ib): the angle that turns n1 towards n2 onto a principal axis of section
    ``p`` and its second moments there, ia = integral of x1'^2 (resisting a displacement
    along the turned n1, U1's I1) and ib = integral of x2'^2 (U1's I2).  Abaqus' I12 is the
    integral of (x1 - x1c)(x2 - x2c) (Analysis User's Guide, "Beam section behavior"; its
    M1 = E (I11 k1 - I12 k2) for the strain ec + k1 x2 - k2 x1)."""
    alpha = 0.5 * math.atan2(2.0 * p.i12, p.i22 - p.i11) if p.i12 else 0.0
    c, s = math.cos(alpha), math.sin(alpha)
    ia = c * c * p.i22 + 2.0 * c * s * p.i12 + s * s * p.i11
    ib = s * s * p.i22 - 2.0 * c * s * p.i12 + c * c * p.i11
    return alpha, ia, ib

MAX_ENTRIES_PER_LINE = 16  # CalculiX hard limit for entries on a data line

# ---------------------------------------------------------------------------
# Conversion report
# ---------------------------------------------------------------------------


# The second line of every deck abq2ccx writes (Report.header_comment_lines).
CONVERTED_MARK = "** Converted from Abaqus to CalculiX by abq2ccx"


class Report:
    """Collects warnings / notes emitted during conversion."""

    def __init__(self) -> None:
        self.entries: List[Tuple[str, str]] = []
        self._seen: set = set()
        self.n_commented = 0          # cards emitted as ** comments (no ccx equivalent)
        # what the ccx model drops or replaces of the Abaqus model (Converter._reduces;
        # kept here so deck reading, mesh generation and assembly flattening record it too)
        self.reduced: List[str] = []
        # the instances of a flattened assembly (flatten_assembly): name, part, ccx label
        # ranges, offsets and renamed sets and surfaces
        self.instances: List[dict] = []

    def reduce(self, what: str) -> None:
        """Record reduced physics: ``what`` part of the Abaqus model the ccx model drops or
        replaces (see Converter.reduced_physics)."""
        if what not in self.reduced:
            self.reduced.append(what)

    def warn(self, msg: str, once: bool = False) -> None:
        if once:
            if msg in self._seen:
                return
            self._seen.add(msg)
        self.entries.append(("WARNING", msg))
        if msg.startswith("[APPROX]"):
            # an --approximate reframing makes ccx solve another model than the deck's
            text = msg[len("[APPROX]"):].strip()
            cuts = [i for i in (text.find(": "), text.find("; "), text.find(" (")) if i >= 25]
            self.reduce("--approximate: " + text[:min(cuts + [len(text), 100])].rstrip(" ,;:."))

    def note(self, msg: str, once: bool = False) -> None:
        if once:
            if msg in self._seen:
                return
            self._seen.add(msg)
        self.entries.append(("NOTE", msg))

    @property
    def n_warnings(self) -> int:
        return sum(1 for level, _ in self.entries if level == "WARNING")

    @property
    def n_notes(self) -> int:
        return sum(1 for level, _ in self.entries if level == "NOTE")

    def summary(self) -> str:
        return (f"{self.n_warnings} warning(s), {self.n_notes} note(s), "
                f"{self.n_commented} commented card(s)")

    def header_comment_lines(self) -> List[str]:
        lines = ["** ====================================================================",
                 f"{CONVERTED_MARK} v{__version__}",
                 f"** {self.summary()} — review below; find commented cards with '** abq2ccx:'.",
                 "** --------------------------------------------------------------------"]
        if not self.entries:
            lines.append("** No conversion issues were flagged.")
        for level, msg in self.entries:
            for i, chunk in enumerate(_wrap(msg, 66)):
                prefix = f"** [{level}] " if i == 0 else "**          "
                lines.append(prefix + chunk)
        for line in self.instance_lines():
            indent = (len(line) - len(line.lstrip())) * " "
            for i, chunk in enumerate(_wrap(line.replace(" -> ", "\0"), 66)):   # keep pairs whole
                lines.append("** " + indent + ("  " if i else "") + chunk.replace("\0", " -> "))
        lines.append("** ====================================================================")
        return lines

    def text(self) -> str:
        lines = [f"[{level}] {msg}" for level, msg in self.entries] or \
            ["No conversion issues were flagged."]
        return "\n".join(lines + self.instance_lines()) + "\n"

    def instance_lines(self, limit: int = 20, names: int = 8) -> List[str]:
        """The instance map of a flattened assembly (none for a flat deck): each instance's
        ccx node and element labels with the offset added to its Abaqus labels, and its
        renamed sets and surfaces; at most ``limit`` instances and ``names`` names each."""
        if not self.instances:
            return []
        lines = ["Instances (ccx label = Abaqus label + offset; Abaqus Instance.name -> ccx name):"]
        for inst in self.instances[:limit]:
            spans = [f"{what} {rng[0]}-{rng[1]} (+{off})" if rng else f"no {what}" for what, rng, off in
                     (("nodes", inst["nodes"], inst["node_offset"]),
                      ("elements", inst["elements"], inst["element_offset"]))]
            ren = [f"{a} -> {c}" for a, c in inst["names"].items()]
            more = [f"+{len(ren) - names} more"] if len(ren) > names else []
            lines.append(f"  {inst['name']} (part {inst['part']}): {', '.join(spans)}"
                         + (f"; {', '.join(ren[:names] + more)}" if ren else ""))
        if len(self.instances) > limit:
            lines.append(f"  ... and {len(self.instances) - limit} more instance(s) (--json lists "
                         f"them all)")
        return lines


def _wrap(text: str, width: int) -> List[str]:
    words, lines, cur = text.split(), [], ""
    for w in words:
        if cur and len(cur) + 1 + len(w) > width:
            lines.append(cur)
            cur = w
        else:
            cur = f"{cur} {w}" if cur else w
    if cur:
        lines.append(cur)
    return lines or [""]


# ---------------------------------------------------------------------------
# Tokenizing: raw text -> list of Block
# ---------------------------------------------------------------------------


@dataclass
class Block:
    """One keyword card and its data lines."""

    keyword: str                                   # upper-case, no leading '*', spaces kept
    params: "OrderedDict[str, Optional[str]]"      # PARAM (upper) -> value (orig case) or None
    data: List[str] = field(default_factory=list)  # raw data lines (comments/newlines stripped)

    def param(self, key: str, default: Optional[str] = None) -> Optional[str]:
        return self.params.get(key.upper(), default)

    def uparam(self, key: str) -> str:
        """The value of parameter ``key``, stripped and upper-cased; "" when it is absent."""
        return (self.params.get(key.upper()) or "").strip().upper()

    def has(self, key: str) -> bool:
        return key.upper() in self.params


# Abaqus permits unambiguous abbreviations of parameter names; CalculiX wants the
# full spelling.  Normalise the common ones that appear in real decks (an unexpanded
# ``AMP=`` on a load card is "parameter not recognized" in ccx, so the load silently
# loses its amplitude).
